<?php
declare(strict_types=1);
session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();
if(($_SESSION['role']??'')!=='pupil'){http_response_code(403);exit('This portal is only available to pupil accounts.');}
$db=db();$uid=(int)$_SESSION['user_id'];$q=$db->prepare("SELECT pa.id account_id,p.id pupil_id,p.school_id,p.first_name,p.middle_name,p.last_name,p.admission_number,p.class_level,p.stream,p.status,s.name school_name FROM pupil_accounts pa JOIN pupils p ON p.id=pa.pupil_id AND p.school_id=pa.school_id JOIN schools s ON s.id=pa.school_id WHERE pa.user_id=? AND pa.active=1 AND p.status='active' LIMIT 1");$q->execute([$uid]);$pupil=$q->fetch();if($pupil){$school=(int)$pupil['school_id'];$pupilId=(int)$pupil['pupil_id'];$q=$db->prepare("SELECT r.academic_year,r.exam_name,r.assessment,r.subject,r.score,r.max_score,r.updated_at FROM pupil_results r JOIN school_exams x ON x.school_id=r.school_id AND x.name=r.exam_name AND x.academic_year=r.academic_year LEFT JOIN school_classes c ON c.id=x.class_id LEFT JOIN school_class_subjects cs ON cs.id=x.subject_id WHERE r.school_id=? AND r.pupil_id=? AND x.status='results_published' AND (x.class_id IS NULL OR c.name=r.class_level) AND (x.subject_id IS NULL OR cs.name=r.subject) ORDER BY r.academic_year DESC,r.updated_at DESC LIMIT 30");$q->execute([$school,$pupilId]);$results=$q->fetchAll();$q=$db->prepare("SELECT r.subject,r.academic_year,x.term,x.exam_date,x.created_at,x.name exam_name,SUM(r.score) score,SUM(r.max_score) max_score FROM pupil_results r JOIN school_exams x ON x.school_id=r.school_id AND x.name=r.exam_name AND x.academic_year=r.academic_year LEFT JOIN school_classes c ON c.id=x.class_id AND c.school_id=x.school_id LEFT JOIN school_class_subjects cs ON cs.id=x.subject_id AND cs.class_id=c.id WHERE r.school_id=? AND r.pupil_id=? AND x.status='results_published' AND (x.class_id IS NULL OR c.name=r.class_level) AND (x.subject_id IS NULL OR cs.name=r.subject) GROUP BY r.subject,r.academic_year,x.id,x.term,x.exam_date,x.created_at,x.name ORDER BY r.subject,r.academic_year DESC,x.exam_date DESC,x.created_at DESC");$q->execute([$school,$pupilId]);$subjectProgress=$q->fetchAll();$q=$db->prepare("SELECT COUNT(DISTINCT a.id) assigned,COUNT(DISTINCT s.assignment_id) submitted,COUNT(DISTINCT CASE WHEN s.status='reviewed' THEN s.assignment_id END) reviewed FROM homework_assignments a LEFT JOIN pupil_homework_submissions s ON s.assignment_id=a.id AND s.school_id=a.school_id AND s.pupil_id=? WHERE a.school_id=? AND a.class_level=? AND a.status='published' AND (a.due_date IS NULL OR a.due_date>=DATE_SUB(CURRENT_DATE,INTERVAL 30 DAY))");$q->execute([$pupilId,$school,$pupil['class_level']]);$homeworkProgress=$q->fetch()?:['assigned'=>0,'submitted'=>0,'reviewed'=>0];$q=$db->prepare("SELECT academic_year,term,published_at FROM pupil_report_cards WHERE school_id=? AND pupil_id=? AND status='published' ORDER BY academic_year DESC,term DESC");$q->execute([$school,$pupilId]);$reportCards=$q->fetchAll();$q=$db->prepare("SELECT id,note_type,subtopic,subject,topic,content,source,updated_at FROM learning_notes WHERE status='published' AND class_level=? AND ((note_type='central' AND school_id IS NULL) OR (note_type='teacher' AND school_id=?)) ORDER BY subject,topic,subtopic LIMIT 100");$q->execute([$pupil['class_level'],$school]);$materials=$q->fetchAll();$q=$db->prepare("SELECT hp.id,hp.title,hp.holiday_period,cs.name subject_name,hp.available_until,COALESCE(pr.status,'assigned') progress_status FROM holiday_packages hp JOIN school_classes c ON c.id=hp.class_id JOIN school_class_subjects cs ON cs.id=hp.subject_id LEFT JOIN holiday_package_progress pr ON pr.package_id=hp.id AND pr.school_id=hp.school_id AND pr.pupil_id=? WHERE hp.school_id=? AND c.name=? AND hp.status='published' AND (hp.available_from IS NULL OR hp.available_from<=CURRENT_DATE) AND (hp.available_until IS NULL OR hp.available_until>=CURRENT_DATE) ORDER BY hp.available_until,hp.title");$q->execute([$pupilId,$school,$pupil['class_level']]);$holidayPackages=$q->fetchAll();$q=$db->prepare('SELECT attendance_status,COUNT(*) total FROM pupil_attendance WHERE school_id=? AND pupil_id=? AND attendance_date>=DATE_SUB(CURRENT_DATE,INTERVAL 30 DAY) GROUP BY attendance_status');$q->execute([$school,$pupilId]);$attendance=$q->fetchAll();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Learner portal · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Learner portal <span>/</span> My learning</div><div class="top-actions"><span class="role-chip">Learner</span><div class="user-name"><?=e((string)($_SESSION['name']??'Pupil'))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">MY LEARNING</div><h1>Hello, <?=e(explode(' ',trim((string)($_SESSION['name']??'Learner')))[0])?></h1><?php if($pupil):?><p class="muted"><?=e($pupil['school_name'].' · '.$pupil['class_level'].($pupil['stream']?' · '.$pupil['stream']:'').' · '.$pupil['admission_number'])?></p><?php else:?><p class="muted">Pupil portal access is not currently linked to an active pupil record.</p><?php endif;?></div></section><?php if(!$pupil):?><section class="empty-state"><h2>Contact your school</h2><p>Your school administrator can activate or restore your learner account.</p></section><?php else:?><section class="metric-grid"><article class="metric-card"><div class="metric-label">PUBLISHED RESULTS</div><div class="metric-value"><?=count($results)?></div><div class="metric-note">Released by your school</div></article><article class="metric-card"><div class="metric-label">LEARNING MATERIALS</div><div class="metric-value"><?=count($materials)?></div><div class="metric-note">Published for your class</div></article><article class="metric-card"><div class="metric-label">ATTENDANCE · LAST 30 DAYS</div><div class="metric-value"><?php $attendanceTotal=array_sum(array_map(fn($row)=>(int)$row['total'],$attendance));?><?=e((string)$attendanceTotal)?></div><div class="metric-note">Recorded school days</div></article><article class="metric-card"><div class="metric-label">SUBJECT SUMMARIES</div><div class="metric-value"><?=count(array_unique(array_column($subjectProgress,'subject')))?></div><div class="metric-note">Subjects with published assessment records</div></article><article class="metric-card"><div class="metric-label">HOMEWORK SUBMITTED</div><div class="metric-value"><?=e((string)$homeworkProgress['submitted'])?> / <?=e((string)$homeworkProgress['assigned'])?></div><div class="metric-note"><?=e((string)$homeworkProgress['reviewed'])?> reviewed � includes current and recent activities</div></article></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">MY RECORD</div><h2>Attendance summary</h2></div></div><?php if($attendance):?><p><?php foreach($attendance as $row):?><span class="count-pill"><?=e(ucfirst($row['attendance_status']).': '.(string)$row['total'])?></span> <?php endforeach;?></p><?php else:?><p class="muted">No attendance has been recorded in the last 30 days.</p><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ACADEMIC PROGRESS</div><h2>Progress by subject</h2><p class="muted">Published assessments are grouped by subject. Scores show marks earned out of available marks; no grade scale is inferred.</p></div></div><?php if($subjectProgress):$groupedProgress=[];foreach($subjectProgress as $progressRow)$groupedProgress[$progressRow['subject']][]=$progressRow;?><div class="question-list"><?php foreach($groupedProgress as $subjectName=>$subjectRows):?><article class="question-card"><h3><?=e($subjectName)?></h3><div class="table-wrap"><table><thead><tr><th>Exam</th><th>Term / year</th><th>Marks</th><th>Percentage</th></tr></thead><tbody><?php foreach($subjectRows as $progressRow):$percentage=(float)$progressRow['max_score']>0?100*(float)$progressRow['score']/(float)$progressRow['max_score']:null;?><tr><td><?=e($progressRow['exam_name'])?></td><td><?=e(($progressRow['term']?:'Term unspecified').' � '.$progressRow['academic_year'])?></td><td><?=e(number_format((float)$progressRow['score'],2).' / '.number_format((float)$progressRow['max_score'],2))?></td><td><?=$percentage===null?'&mdash;':e(number_format($percentage,1).'%')?></td></tr><?php endforeach;?></tbody></table></div></article><?php endforeach;?></div><?php else:?><div class="empty-state"><h3>No published assessment records yet</h3><p>Subject summaries will appear after your school publishes results.</p></div><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ACADEMIC PROGRESS</div><h2>Published results</h2></div></div><?php if($results):?><div class="table-wrap"><table><thead><tr><th>Year</th><th>Exam</th><th>Subject</th><th>Assessment</th><th>Score</th></tr></thead><tbody><?php foreach($results as $row):?><tr><td><?=e((string)$row['academic_year'])?></td><td><?=e($row['exam_name'])?></td><td><?=e($row['subject'])?></td><td><?=e($row['assessment'])?></td><td><?=e(number_format((float)$row['score'],2).' / '.number_format((float)$row['max_score'],2))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No published results yet</h3><p>Your results will appear here after the school publishes them.</p></div><?php endif;?></section><?php if($reportCards):?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ACADEMIC PROGRESS</div><h2>Published report cards</h2></div></div><div class="question-list"><?php foreach($reportCards as $card):?><article class="question-card"><h3><?=e($card['academic_year'].' � '.($card['term']?:'Unspecified term'))?></h3><a class="button" href="report_card.php?academic_year=<?=$card['academic_year']?>&amp;term=<?=rawurlencode($card['term'])?>">View report card</a></article><?php endforeach;?></div></section><?php endif;?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">CLASS RESOURCES</div><h2>Learning materials</h2><p class="muted">Published class materials from your school and the central curriculum library.</p></div></div><?php if($materials):?><div class="question-list"><?php foreach($materials as $material):?><article class="question-card"><div class="section-heading"><div><h3><?=e($material['subtopic'])?></h3><p class="muted"><?=e(trim(($material['subject']??'').' · '.($material['topic']??''), ' ·'))?></p></div><span class="count-pill"><?=e($material['note_type']==='central'?'Curriculum':'School')?></span></div><div class="learner-material-content"><?=nl2br(e($material['content']))?></div><?php if($material['source']):?><p class="muted">Source: <?=e($material['source'])?></p><?php endif;?></article><?php endforeach;?></div><?php else:?><div class="empty-state"><h3>No materials published</h3><p>Your teachers’ and curriculum materials will appear here when published for your class.</p></div><?php endif;?></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">HOLIDAY LEARNING</div><h2>Class holiday packages</h2><p class="muted">Available learning for your class during the holiday period.</p></div></div><?php if($holidayPackages):?><div class="question-list"><?php foreach($holidayPackages as $package):?><article class="question-card"><h3><?=e($package['title'])?></h3><p class="muted"><?=e($package['subject_name'].' · '.$package['holiday_period'])?></p><p>Progress: <?=e(ucwords(str_replace('_',' ',$package['progress_status'])))?></p><a class="button primary" href="holiday_package.php?id=<?=$package['id']?>">Open package</a></article><?php endforeach;?></div><?php else:?><p class="muted">No holiday packages are available for your class today.</p><?php endif;?></section><?php endif;?><footer class="page-footer">ShuleLite <span>·</span> Learner portal</footer></div></main></div></body></html>